\label{def1}
For $p\in \mathbb Z$ and $m, r, t \in \mathbb N$, define the quantities $S(p,m,t,r,0)$ and $S(p,m,1,r,1)$ as
\begin{align*}
&S(p,m,t,r,0):=\sum_{n=1}^\infty\frac{H_n^{(p)}}{n^{m}(n+r)^{t}}\,,\\
&S(p,m,t,r,1):=\sum_{n=1}^\infty\frac{(-1)^{n+1} H_n^{(p)}}{n^{m}(n+r)^{t}}\,.
\end{align*}
When $p \geq 0$, $H_n^{(-p)}$ is understood to be the sum $1^p+2^p+\cdots+n^p$.

\label{lem1}
Let $s$ be a positive integer and $a>0$, then
\begin{align*}
\sum_{n=1}^\infty\frac{a H_n^{(s)}}{n(n+a)}
&=\zeta(s+1)+\sum_{j=1}^{a-1}\frac{(-1)^{s+1}H_j}{j^s}+\sum_{i=2}^s(-1)^{s-i}H_{a-1}^{(s-i+1)}\zeta(i)\,.
\end{align*}

\label{lem2}
Let $p, m, r \in \mathbb N$, then we have
\begin{align*}
S(p,m,1,r,0)
&=\sum_{i=2}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}S_{p,i}^{+,+}+\frac{(-1)^{m-1}}{r^{m}}\zeta(p+1)\\
&\quad +\frac{(-1)^{m-1}}{r^{m}}\left(\sum_{j=1}^{r-1}\frac{(-1)^{p+1}H_j}{j^p}
+\sum_{\ell=2}^{p}(-1)^{p-\ell}H_{r-1}^{(p-\ell+1)}\zeta(\ell)\right)\,.
\end{align*}
Let $m, r \in \mathbb N$, $p \in \mathbb N_{0}$ and $m \geq p+2$, then we have
\begin{align*}
&S(-p,m,1,r,0)\\
&=\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+}
\left(\sum_{i=2}^{m-p-1+\ell}\frac{(-1)^{m-p-1+\ell-i}}{r^{m-p+\ell-i}}\zeta(i)
+\frac{(-1)^{m-p-2+\ell}}{r^{m-p-1+\ell}} H_{r}\right)\,.
\end{align*}

When $p, m, r \in \mathbb N$, we can obtain that
\begin{align*}
\sum_{n=1}^\infty\frac{H_n^{(p)}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty H_n^{(p)}\left(\sum_{i=2}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}n^{i}}
+\frac{(-1)^{m-1}}{r^{m-1}n(n+r)}\right)\\
&=\sum_{i=2}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}\sum_{n=1}^\infty \frac{H_n^{(p)}}{n^{i}}
+\frac{(-1)^{m-1}}{r^{m-1}}\sum_{n=1}^\infty\frac{H_n^{(p)}}{n(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem1}}, we get the desired result.


When $m, r \in \mathbb N$, $p \in \mathbb N_{0}$ and $m \geq p+2$, we have
\begin{align*}
\sum_{n=1}^\infty\frac{H_n^{(-p)}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty\frac{\sum_{\ell=1}^{n}\ell^{p}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+}n^{p+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+} \sum_{n=1}^\infty \frac{1}{n^{m-p-1+\ell}(n+r)}\,.
\end{align*}
With the help of partial fraction expansion
\begin{align*}
\frac{1}{n^{t}(n+r)}
=\sum_{i=2}^{t}\frac{(-1)^{t-i}}{r^{t-i+1}}\cdot\frac{1}{n^{i}}
+\frac{(-1)^{t-1}}{r^{t-1}}\cdot\frac{1}{n(n+r)},
\end{align*}
we get the desired result.

\label{lem3}
Let $p, r \in \mathbb N$, defining
\begin{align*}
S(p,r,1):=\sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p)}}{n+r}\,,
\end{align*}
then we have
\begin{align*}
&S(p,r,1)\\
&=(-1)^{r}S_{p,1}^{+,-}+(-1)^{r-1}\overline{\zeta}(p+1)
+\sum_{j=1}^{p}(-1)^{p-j+r}\overline{\zeta}(j)\overline{H}_{r-1}^{(p-j+1)}\\
&\quad +(-1)^{p+r-1}\overline{\zeta}(1)H_{r-1}^{(p)}
+(-1)^{p+r}\sum_{n=1}^{r-1}\frac{\overline{H}_{n}}{n^{p}}\,.
\end{align*}

By a change of counter, we have
\begin{align*}
&\quad S(p,r,1)\\
&=\sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p)}}{n+r}\\
&=\sum_{n=1}^\infty \frac{(-1)^{n}H_n^{(p)}}{n+r-1}-\sum_{n=1}^\infty \frac{(-1)^{n}}{n^{p}(n+r-1)}\\
&=-S(p,r-1,1)+\sum_{n=1}^\infty (-1)^{n+1}\left(\sum_{j=1}^{p}\frac{(-1)^{p-j}}{(r-1)^{p-j+1}}\cdot\frac{1}{n^{j}}
+\frac{(-1)^{p}}{(r-1)^{p}}\cdot\frac{1}{n+r-1}\right)\\
&=-S(p,r-1,1)+\sum_{j=1}^{p}\frac{(-1)^{p-j}}{(r-1)^{p-j+1}}\overline{\zeta}(j)
+\frac{(-1)^{p+r-1}}{(r-1)^{p}}(\overline{\zeta}(1)-\overline{H}_{r-1})\\
&=(-1)^{r-1}S(p,1,1)+\sum_{j=1}^{p}\overline{\zeta}(j)\sum_{n=1}^{r-1}\frac{(-1)^{p-j+r-1-n}}{n^{p-j+1}}\\
&\quad \quad +(-1)^{p+r-1}\overline{\zeta}(1)\sum_{n=1}^{r-1}\frac{1}{n^{p}}
+(-1)^{p+r}\sum_{n=1}^{r-1}\frac{\overline{H}_{n}}{n^{p}}\\
&=(-1)^{r-1}S(p,1,1)+\sum_{j=1}^{p}\overline{\zeta}(j)(-1)^{p-j+r}\overline{H}_{r-1}^{(p-j+1)}\\
&\quad \quad +(-1)^{p+r-1}\overline{\zeta}(1)H_{r-1}^{(p)}+(-1)^{p+r}\sum_{n=1}^{r-1}\frac{\overline{H}_{n}}{n^{p}}\,.
\end{align*}
Since
\begin{align*}
S(p,1,1)=\sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p)}}{n+1}=-S_{p,1}^{+,-}+\overline{\zeta}(p+1)\,,
\end{align*}
we get the desired result.

\label{lem4}
Let $p, m, r \in \mathbb N$, then we have
\begin{align*}
&\quad S(p,m,1,r,1)\\
&=\sum_{i=1}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}S_{p,i}^{+,-}+\frac{(-1)^{m+r}}{r^{m}}S_{p,1}^{+,-}
+\frac{(-1)^{m+r-1}}{r^{m}}\overline{\zeta}(p+1)\\
&\quad +\frac{(-1)^{m}}{r^{m}}\left(\sum_{j=1}^{p}(-1)^{p-j+r}\overline{\zeta}(j)\overline{H}_{r-1}^{(p-j+1)}
+(-1)^{p+r-1}\overline{\zeta}(1)H_{r-1}^{(p)}\right)\\
&\quad +\frac{(-1)^{m+p+r}}{r^{m}}\sum_{n=1}^{r-1}\frac{\overline{H}_{n}}{n^{p}}\,.
\end{align*}
Let $m, r \in \mathbb N$, $p \in \mathbb N_{0}$ and $m \geq p+1$, then we have
{\scriptsize
\begin{align*}
&S(-p,m,1,r,1)\\
&=\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+}
\left(\sum_{i=1}^{m-p-1+\ell}\frac{(-1)^{m-p-1+\ell-i}}{r^{m-p+\ell-i}}\zeta(i)
+\frac{(-1)^{m-p-1+\ell+r}}{r^{m-p-1+\ell}}(\overline{\zeta}(1)-\overline{H}_{r})\right)\,.
\end{align*}
}

When $p, m, r \in \mathbb N$, we can obtain that
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p)}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty (-1)^{n+1}H_n^{(p)}\left(\sum_{i=1}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}n^{i}}
+\frac{(-1)^{m}}{r^{m}(n+r)}\right)\\
&=\sum_{i=1}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}\sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p)}}{n^{i}}
+\frac{(-1)^{m}}{r^{m}}\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p)}}{n+r}\,.
\end{align*}
With the help of Lemma {\ref{lem3}}, we get the desired result.


When $m, r \in \mathbb N$, $p \geq 0$ and $m \geq p+1$, we have
\begin{align*}
\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(-p)}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty\frac{(-1)^{n+1}\sum_{\ell=1}^{n}\ell^{p}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{(-1)^{n+1}\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+}n^{p+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{p+1}\sum_{\ell=0}^{p} \binom{p+1}{\ell}B_{\ell}^{+} \sum_{n=1}^\infty \frac{(-1)^{n+1}}{n^{m-p-1+\ell}(n+r)}\,.
\end{align*}
With the help of partial fraction expansion
\begin{align*}
\frac{1}{n^{t}(n+r)}
=\sum_{i=1}^{t}\frac{(-1)^{t-i}}{r^{t-i+1}}\cdot\frac{1}{n^{i}}
+\frac{(-1)^{t}}{r^{t}}\cdot\frac{1}{n+r},
\end{align*}
we get the desired result.

\label{maintheorem1}
Let $s, p, m, k \in \mathbb N$ with $m \geq s$, then we have,
\begin{align*}
\sum_{n=1}^\infty\frac{H_n^{(p,s)}}{n^{m}\binom{n+k}{k}}
=\sum_{\ell_{1}=0}^{s-1} \sum_{\ell_{2}=0}^{s-1-\ell_{1}}a(s,\ell_{1},\ell_{2})
\sum_{r=1}^{k}(-1)^{r+1} r \binom{k}{r} S(p-\ell_{1},m-\ell_{2},1,r,0)\,,
\end{align*}
where $S(p-\ell_{1},m-\ell_{2},1,r,0)$ is given in Lemma \ref{lem2} and $a(s,\ell_{1},\ell_{2})$ is given in Lemma \ref{lem5}.
Therefore generalized hyperharmonic number sum
$$
\sum_{n=1}^\infty\frac{H_n^{(p,s)}}{n^{m}\binom{n+k}{k}}
$$
can be expressed in terms of classical Euler sums, zeta values and generalized harmonic numbers.

\label{maintheorem2}
Let $s, p, m, k \in \mathbb N$ with $m \geq s$, then we have,
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p,s)}}{n^{m}\binom{n+k}{k}}\\
&=\sum_{\ell_{1}=0}^{s-1} \sum_{\ell_{2}=0}^{s-1-\ell_{1}}a(s,\ell_{1},\ell_{2})
\sum_{r=1}^{k}(-1)^{r+1} r \binom{k}{r} S(p-\ell_{1},m-\ell_{2},1,r,1)\,,
\end{align*}
where $S(p-\ell_{1},m-\ell_{2},1,r,1)$ is given in Lemma \ref{lem4}.
Therefore generalized hyperharmonic number sum
$$
\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p,s)}}{n^{m}\binom{n+k}{k}}
$$
can be expressed in terms of classical alternating Euler sums, zeta values and generalized (alternating) harmonic numbers.

Some illustrative examples are as following.


When $s=2, p=2, m=3, k=2$, we have
\begin{align*}
&\sum_{n=1}^\infty\frac{H_n^{(2,2)}}{n^{3}\binom{n+2}{2}}
=-\frac{9}{2}\zeta(5)+\frac{25}{4}\zeta(3)-\frac{17}{720}\pi^{4}-\frac{1}{4}\pi^{2}\,,\\
&\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(2,2)}}{n^{3}\binom{n+2}{2}}
=S_{2,3}^{+,-}-\frac{1}{2}S_{2,2}^{+,-}+\frac{3}{16}\zeta(3)-S_{1,3}^{+,-}
+\frac{3}{2}S_{1,2}^{+,-}-4S_{1,1}^{+,-}+\zeta(2)\,.
\end{align*}



When $s=2, p=1, m=3, k=2$, we have
\begin{align*}
\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(1,2)}}{n^{3}\binom{n+2}{2}}
&=S_{1,3}^{+,-}-\frac{1}{2}S_{1,2}^{+,-}-\frac{1}{2}\log{2}-\frac{7}{8}\zeta(2)+\frac{3}{2}\,,\\
&=-2Li_{4}(\frac{1}{2})+\frac{11}{4}\zeta(4)+\frac{1}{2}\zeta(2){\log{2}}^{2}-\frac{1}{12}(\log{2})^{4}\\
&\quad -\frac{7}{4}\zeta(3)\log{2}-\frac{5}{16}\zeta(3)-\frac{7}{8}\zeta(2)
-\frac{1}{2}\log{2}+\frac{3}{2}\,.
\end{align*}
In this expression we use the well-known polylogarithm function
$$
Li_{p}(x):=\sum_{n=1}^\infty \frac{x^n}{n^p}\quad (\lvert x \lvert \leq 1,\quad p \in \mathbb N)\,.
$$

\label{lem6}
Let $\{f_k\}$ and $\{g_k\}$ be two sequences, and define the forward difference and backward difference, respectively, as
$$
\Delta\tau_k=\tau_{k+1}-\tau_k\quad\hbox{and}\quad \nabla\tau_k=\tau_k-\tau_{k-1}\,,
$$
then, there holds the relation:
\begin{align*}
\sum_{k=1}^\infty f_k\nabla g_k=\lim_{n\to\infty}f_n g_n-f_1 g_0-\sum_{k=1}^\infty g_k \Delta f_k \,.
\end{align*}

\label{def2}
For $p_{1}, p_{2}\in \mathbb Z$ and $m, r, t \in \mathbb N$, define the quantities $T(p_{1},p_{2},m,t,r,0)$ and $T(p_{1},p_{2},m,t,r,1)$ as
\begin{align*}
&T(p_{1},p_{2},m,t,r,0):=\sum_{n=1}^\infty\frac{H_n^{(p_{1})}H_n^{(p_{2})}}{n^{m}(n+r)^{t}}\,,\\
&T(p_{1},p_{2},m,t,r,1):=\sum_{n=1}^\infty\frac{(-1)^{n+1} H_n^{(p_{1})}H_n^{(p_{2})}}{n^{m}(n+r)^{t}}\,.
\end{align*}
When $p \geq 0$, $H_n^{(-p)}$ is understood to be the sum $1^p+2^p+\cdots+n^p$.

When $p_{1}, p_{2}, m, r \in \mathbb N$, we can obtain that
\begin{align*}
\sum_{n=1}^\infty\frac{H_n^{(p_{1})}H_n^{(p_{2})}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty H_n^{(p_{1})}H_n^{(p_{2})}\left(\sum_{i=2}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}n^{i}}
+\frac{(-1)^{m-1}}{r^{m-1}n(n+r)}\right)\\
&=\sum_{i=2}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}\sum_{n=1}^\infty \frac{H_n^{(p_{1})}H_n^{(p_{2})}}{n^{i}}
+\frac{(-1)^{m-1}}{r^{m-1}}\sum_{n=1}^\infty\frac{H_n^{(p_{1})}H_n^{(p_{2})}}{n(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem7}}, we get the desired result.


When $p_{1}, m, r \in \mathbb N$, $p_{2} \in \mathbb N_{0}$ and $m \geq p_{2}+2$, we have
\begin{align*}
\sum_{n=1}^\infty\frac{H_n^{(p_{1})}H_n^{(-p_{2})}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty\frac{H_n^{(p_{1})}\sum_{\ell=1}^{n}\ell^{p_{2}}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{H_n^{(p_{1})}\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+}n^{p_{2}+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+} \sum_{n=1}^\infty \frac{H_n^{(p_{1})}}{n^{m-p_{2}-1+\ell}(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem2}}, we get the desired result.


When $m, r \in \mathbb N$, $p_{1}, p_{2} \in \mathbb N_{0}$ and $m \geq p_{1}+p_{2}+3$, we have
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{H_n^{(-p_{1})}H_n^{(-p_{2})}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty\frac{\sum_{\ell_{1}=1}^{n}\ell^{p_{1}}\sum_{\ell_{2}=1}^{n}\ell^{p_{2}}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{\frac{1}{p_{1}+1}\sum_{\ell=0}^{p_{1}} \binom{p_{1}+1}{\ell}B_{\ell}^{+}n^{p_{1}+1-\ell}\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+}n^{p_{2}+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{(p_{1}+1)(p_{2}+1)}\sum_{\ell_{1}=0}^{p_{1}} \sum_{\ell_{2}=0}^{p_{2}} \binom{p_{1}+1}{\ell_{1}}\binom{p_{2}+1}{\ell_{2}}\\
&\quad \times B_{\ell_{1}}^{+}B_{\ell_{2}}^{+} \sum_{n=1}^\infty \frac{1}{n^{m-p_{1}-p_{2}-2+\ell_{1}+\ell_{2}}(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem2}}, we get the desired result.

When $p_{1}, p_{2}, r \in \mathbb N$ and $m \in \mathbb N_{0}$, we can obtain that
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1})}H_n^{(p_{2})}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty (-1)^{n+1}H_n^{(p_{1})}H_n^{(p_{2})}\left(\sum_{i=1}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}n^{i}}
+\frac{(-1)^{m}}{r^{m}(n+r)}\right)\\
&=\sum_{i=1}^{m}\frac{(-1)^{m-i}}{r^{m-i+1}}\sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p_{1})}H_n^{(p_{2})}}{n^{i}}
+\frac{(-1)^{m}}{r^{m}}\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1})}H_n^{(p_{2})}}{n+r}\,.
\end{align*}
With the help of Lemma {\ref{lem9}}, we get the desired result.


When $p_{1}, m, r \in \mathbb N$, $p_{2} \in \mathbb N_{0}$ and $m \geq p_{2}+1$, we have
\begin{align*}
\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1})}H_n^{(-p_{2})}}{n^{m}(n+r)}
&=\sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1})}\sum_{\ell=1}^{n}\ell^{p_{2}}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{(-1)^{n+1}H_n^{(p_{1})}\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+}n^{p_{2}+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+} \sum_{n=1}^\infty \frac{(-1)^{n+1}H_n^{(p_{1})}}{n^{m-p_{2}-1+\ell}(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem4}}, we get the desired result.


When $m, r \in \mathbb N$, $p_{1}, p_{2} \in \mathbb N_{0}$ and $m \geq p_{1}+p_{2}+2$, we have
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(-p_{1})}H_n^{(-p_{2})}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty\frac{(-1)^{n+1}\sum_{\ell_{1}=1}^{n}\ell^{p_{1}}\sum_{\ell_{2}=1}^{n}\ell^{p_{2}}}{n^{m}(n+r)}\\
&=\sum_{n=1}^\infty
\frac{(-1)^{n+1}\frac{1}{p_{1}+1}\sum_{\ell=0}^{p_{1}} \binom{p_{1}+1}{\ell}B_{\ell}^{+}n^{p_{1}+1-\ell}\frac{1}{p_{2}+1}\sum_{\ell=0}^{p_{2}} \binom{p_{2}+1}{\ell}B_{\ell}^{+}n^{p_{2}+1-\ell}}{n^{m}(n+r)}\\
&=\frac{1}{(p_{1}+1)(p_{2}+1)}\sum_{\ell_{1}=0}^{p_{1}} \sum_{\ell_{2}=0}^{p_{2}} \binom{p_{1}+1}{\ell_{1}}\binom{p_{2}+1}{\ell_{2}}\\
&\quad \times B_{\ell_{1}}^{+}B_{\ell_{2}}^{+} \sum_{n=1}^\infty \frac{(-1)^{n+1}}{n^{m-p_{1}-p_{2}-2+\ell_{1}+\ell_{2}}(n+r)}\,.
\end{align*}
With the help of Lemma {\ref{lem4}}, we get the desired result.

\label{maintheorem3}
Let $s_{1}, s_{2}, p_{1}, p_{2}, m, k \in \mathbb N$ with $m \geq s_{1}+s_{2}-1$, then we have
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{H_n^{(p_{1},s_{1})}H_n^{(p_{2},s_{2})}}{n^{m}\binom{n+k}{k}}\\
&=\sum_{\ell_{1}=0}^{s_{1}-1}\sum_{t_{1}=0}^{s_{1}-1-\ell_{1}}
\sum_{\ell_{2}=0}^{s_{2}-1}\sum_{t_{2}=0}^{s_{2}-1-\ell_{2}}a(s_{1},\ell_{1},t_{1})a(s_{2},\ell_{2},t_{2})\\
&\quad \times \sum_{r=1}^{k}(-1)^{r+1} r \binom{k}{r} T(p_{1}-\ell_{1},p_{2}-\ell_{2},m-t_{1}-t_{2},1,r,0)\,,
\end{align*}
where $a(s,\ell_{x},t_{x}), x=1,2$ are given in Lemma \ref{lem5} and $T(p_{1}-\ell_{1},p_{2}-\ell_{2},m-t_{1}-t_{2},1,r,0)$ is given in Lemma \ref{lem8}.
Therefore generalized hyperharmonic number sum
$$
 \sum_{n=1}^\infty\frac{H_n^{(p_{1},s_{1})}H_n^{(p_{2},s_{2})}}{n^{m}\binom{n+k}{k}}
$$
can be expressed in terms of classical Euler sums, zeta values and generalized harmonic numbers.

\label{maintheorem4}
Let $s_{1}, s_{2}, p_{1}, p_{2}, m, k \in \mathbb N$ with $m \geq s_{1}+s_{2}-1$, then we have
\begin{align*}
&\quad \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1},s_{1})}H_n^{(p_{2},s_{2})}}{n^{m}\binom{n+k}{k}}\\
&=\sum_{\ell_{1}=0}^{s_{1}-1}\sum_{t_{1}=0}^{s_{1}-1-\ell_{1}}
\sum_{\ell_{2}=0}^{s_{2}-1}\sum_{t_{2}=0}^{s_{2}-1-\ell_{2}}a(s_{1},\ell_{1},t_{1})a(s_{2},\ell_{2},t_{2})\\
&\quad \times \sum_{r=1}^{k}(-1)^{r+1} r \binom{k}{r} T(p_{1}-\ell_{1},p_{2}-\ell_{2},m-t_{1}-t_{2},1,r,1)\,,
\end{align*}
where $a(s,\ell_{x},t_{x}), x=1,2$ are given in Lemma \ref{lem5} and $T(p_{1}-\ell_{1},p_{2}-\ell_{2},m-t_{1}-t_{2},1,r,1)$ is given in Lemma \ref{lem10}.
Therefore generalized hyperharmonic number sum
$$
 \sum_{n=1}^\infty\frac{(-1)^{n+1}H_n^{(p_{1},s_{1})}H_n^{(p_{2},s_{2})}}{n^{m}\binom{n+k}{k}}
$$
can be expressed in terms of classical (alternating) Euler sums, zeta values and generalized (alternating) harmonic numbers.

