\label{lem11}
Let $n, m \in \mathbb N_{0}$, defining
\begin{align*}
L(n, m, x):=\int_{0}^{x}y^{n}\log^{m} y \mathrm{d}y\,,
\end{align*}
then we have
\begin{align*}
L(n, m, x)=\frac{x^{n+1}}{n+1}\sum_{j=0}^{m}\frac{(m+1-j)_{j}}{(n+1)^j}(-1)^{j}\log^{m-j} x\,,
\end{align*}
where $(t)_{n}=t(t+1)\cdots(t+n-1)$ is the Pochhammer symbol. In particular, we have $L(n, m, 1)=\frac{m!(-1)^m}{(n+1)^{m+1}}$.

\begin{align*}
L(n, m, x)&=\frac{x^{n+1}}{n+1}\log^{m} x-\frac{m}{n+1}\int_{0}^{x}y^{n}\log^{m-1} y \mathrm{d}y\\
&=\frac{x^{n+1}}{n+1}\log^{m} x-\frac{m}{n+1}L(n, m-1, x)\\
&=\frac{x^{n+1}}{n+1}\log^{m} x-\frac{m x^{n+1}}{(n+1)^2}\log^{m-1} x+\frac{m(m-1)}{(n+1)^2}L(n, m-2, x)\\
&=\frac{x^{n+1}}{n+1}\sum_{j=0}^{m}\frac{(m+1-j)_{j}}{(n+1)^j}(-1)^{j}\log^{m-j} x\,.
\end{align*}

\label{lem12}
Let $n, m \in \mathbb N_{0}$, defining
\begin{align*}
M(n, m, x):=\int_{x}^{1}y^{n}\log^{m} (1-y) \mathrm{d}y\,,
\end{align*}
then we have
\begin{align*}
M(n, m, x)=\sum_{j=0}^{n}\binom{n}{j}(-1)^{j}\frac{(1-x)^{j+1}}{j+1}
\sum_{i=0}^{m}\frac{(m+1-i)_{i}}{(j+1)^i}(-1)^{i}\log^{m-i} (1-x)\,.
\end{align*}
In particular, we have $M(n, m, 0)=(-1)^{m}m!\sum_{j=0}^{n}\binom{n}{j}\frac{(-1)^{j}}{(j+1)^{m+1}}$.

By a change of variable, we have
\begin{align*}
M(n, m, x)&=\int_{0}^{1-x}(1-t)^{n}\log^{m} t \mathrm{d}t\\
&=\sum_{j=0}^{n}\binom{n}{j}(-1)^{j}\int_{0}^{1-x}t^{j}\log^{m} t \mathrm{d}t\,.
\end{align*}
With the help of Lemma\ref{lem11}, we get the desired result.
